3	const key = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighbors = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	export const nextGeneration = (liveCells: Cell[]): Cell[] => {
17	  const living = new Set(liveCells.map(key));
18	  const liveNeighborCount = (cell: Cell): number =>
19	    neighbors(cell).filter((neighbor) => living.has(key(neighbor))).length;
20	
21	  const candidates = new Map<string, Cell>();
22	  for (const cell of liveCells) {
23	    candidates.set(key(cell), cell);
24	    for (const neighbor of neighbors(cell)) {
25	      candidates.set(key(neighbor), neighbor);
26	    }
27	  }
28	
29	  return [...candidates.values()].filter((cell) => {
30	    const count = liveNeighborCount(cell);
31	    return living.has(key(cell)) ? count === 2 || count === 3 : count === 3;
32	  });
33	};
